private static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep == 0) {
        return timeBucket;
    }
    int date = (int) (timeBucket / 100);
    int time = (int) (timeBucket % 100);
    int step = (dayStep > 0) ? dayStep : -dayStep;
    int diff = (int) ((date - 1) % step);
    if (diff >= step / 2) {
        date -= diff;
    } else {
        date -= step - diff;
    }
    return (time < 10 ? 10 : time) + date * 100L;
}

/**
 * Follow the dayStep to re-format the time bucket literal long value. Such as, in dayStep == 11, 20000105 re-formatted time bucket is 20000101, 20000115 re-formatted time bucket is 20000112, 20000123 re-formatted time bucket is 20000123
 */
static long compressTimeBucket(long timeBucket,int dayStep){
    if(dayStep < 2 || dayStep > 31){
        throw new IllegalArgumentException("Invalid day step: "+dayStep);
    }
    long tempTimeBucket = timeBucket / (dayStep * 10000);
    return tempTimeBucket * (dayStep * 10000) + (dayStep == 31 ? 1000000 : 0);
}
