    if (graph == null) {
        return false;
    }

    // Check if the vertices set is empty
    if (vertices.isEmpty()) {
        return false;
    }

    // Check if the graph contains all the vertices
    if (!graph.containsAll(vertices)) {
        return false;
    }

    // Create a list of edges to check
    List<E> edges = new ArrayList<>();

    // Iterate through the vertices and add the edges to the list
    for (V vertex : vertices) {
        for (E edge : graph.getAllEdges(vertex)) {
            edges.add(edge);
        }
    }

    // Check if all the vertices are connected by an edge
    for (V vertex : vertices) {
        int connectedEdges = 0;
        for (E edge : edges) {
            if (graph.getEdge(edge).contains(vertex)) {
                connectedEdges++;
            }
        }
        if (connectedEdges != vertices.size() - 1) {
